import asyncio
from dataclasses import dataclass, field
from datetime import datetime, timezone
from hashlib import sha256
import hmac
import json
import logging
from typing import Mapping
from urllib.parse import urlsplit

import httpx

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class Destination:
    url: str
    allowed_hosts: frozenset[str]
    signing_key: bytes = field(repr=False)
    enabled: bool = True
    max_attempts: int = 4


@dataclass(frozen=True)
class Delivery:
    event_id: str
    event_type: str
    tenant_id: str
    data: Mapping[str, object]
    created_at: datetime


@dataclass(frozen=True)
class Attempt:
    event_id: str
    number: int
    status_code: int | None
    retryable: bool
    message: str


def validate_destination(destination: Destination) -> None:
    parsed = urlsplit(destination.url)
    if parsed.scheme != "https" or parsed.hostname not in destination.allowed_hosts:
        raise ValueError("destination is outside the tenant allowlist")
    if parsed.username or parsed.password or parsed.fragment:
        raise ValueError("destination URL contains unsupported components")


def encode_event(delivery: Delivery) -> bytes:
    if delivery.created_at.tzinfo is None:
        raise ValueError("event timestamp must be timezone-aware")
    envelope = {
        "id": delivery.event_id,
        "type": delivery.event_type,
        "tenant": delivery.tenant_id,
        "created_at": delivery.created_at.astimezone(timezone.utc).isoformat(),
        "data": dict(delivery.data),
    }
    return json.dumps(envelope, sort_keys=True, separators=(",", ":")).encode("utf-8")


def signature_for(key: bytes, timestamp: int, body: bytes) -> str:
    signed = str(timestamp).encode("ascii") + b"." + body
    return hmac.new(key, signed, sha256).hexdigest()


def headers_for(destination: Destination, delivery: Delivery, body: bytes) -> dict[str, str]:
    timestamp = int(datetime.now(timezone.utc).timestamp())
    return {
        "Content-Type": "application/json",
        "X-Event-Id": delivery.event_id,
        "X-Event-Type": delivery.event_type,
        "X-Delivery-Timestamp": str(timestamp),
        "X-Delivery-Signature": signature_for(destination.signing_key, timestamp, body),
        "User-Agent": "Acme-Events/2",
    }


def should_retry(status_code: int | None) -> bool:
    return status_code is None or status_code in {408, 425, 429} or status_code >= 500


def retry_delay(attempt: int, retry_after: str | None) -> float:
    if retry_after and retry_after.isdecimal():
        return min(float(retry_after), 60.0)
    return min(float(2 ** (attempt - 1)), 30.0)


def classify_response(event_id: str, number: int, response: httpx.Response) -> Attempt:
    status_code = response.status_code
    if 200 <= status_code < 300:
        return Attempt(event_id, number, status_code, False, "delivered")
    return Attempt(
        event_id,
        number,
        status_code,
        should_retry(status_code),
        f"remote returned HTTP {status_code}",
    )


def classify_exception(event_id: str, number: int, exc: httpx.RequestError) -> Attempt:
    logger.warning("delivery transport failed for event %s: %s", event_id, type(exc).__name__)
    return Attempt(event_id, number, None, True, type(exc).__name__)


async def send_once(
    destination: Destination,
    delivery: Delivery,
    body: bytes,
    number: int,
) -> tuple[Attempt, float]:
    headers = headers_for(destination, delivery, body)
    try:
        async with httpx.AsyncClient(follow_redirects=True, timeout=8.0) as client:
            response = await client.post(destination.url, content=body, headers=headers)
    except httpx.RequestError as exc:
        return classify_exception(delivery.event_id, number, exc), retry_delay(number, None)
    attempt = classify_response(delivery.event_id, number, response)
    delay = retry_delay(number, response.headers.get("Retry-After")) if attempt.retryable else 0.0
    return attempt, delay


async def deliver(destination: Destination, delivery: Delivery) -> list[Attempt]:
    if not destination.enabled:
        return []
    validate_destination(destination)
    body = encode_event(delivery)
    attempts: list[Attempt] = []
    for number in range(1, destination.max_attempts + 1):
        result, delay = await send_once(destination, delivery, body, number)
        attempts.append(result)
        if not result.retryable:
            break
        if number < destination.max_attempts:
            await asyncio.sleep(delay)
    return attempts


def delivery_summary(attempts: list[Attempt]) -> dict[str, object]:
    if not attempts:
        return {"state": "skipped", "attempts": 0}
    last = attempts[-1]
    if last.message == "delivered":
        state = "delivered"
    elif last.retryable:
        state = "exhausted"
    else:
        state = "rejected"
    return {
        "state": state,
        "attempts": len(attempts),
        "last_status": last.status_code,
        "event_id": last.event_id,
    }


def redact_url(destination: Destination) -> str:
    parsed = urlsplit(destination.url)
    host = parsed.hostname or "invalid"
    return f"{parsed.scheme}://{host}/..."


def log_summary(destination: Destination, attempts: list[Attempt]) -> None:
    summary = delivery_summary(attempts)
    logger.info(
        "delivery %s to %s after %d attempts",
        summary["state"],
        redact_url(destination),
        summary["attempts"],
    )
